#include <signal.h>
#include <stdlib.h>
#include <unistd.h>
#include <stdbool.h>

volatile sig_atomic_t handler_invoked = false;

void signal_handler(int signum) {
    handler_invoked = true;
}

int main() {
    struct sigaction sa, current_sa;
    int pipefd[2];
    char buf;

    // Create a pipe for synchronization
    if (pipe(pipefd) == -1) {
        exit(EXIT_FAILURE); // Exit with a generic failure code if pipe creation fails
    }

    // Setup the signal handler
    sa.sa_handler = signal_handler;
    sa.sa_flags = SA_RESETHAND; // Reset the signal handler to default after first delivery
    sigemptyset(&sa.sa_mask);

    // Set the action for SIGINT
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        exit(EXIT_FAILURE); // Exit with a generic failure code if sigaction fails to set the handler
    }

    // Sanity check: verify the current signal handler for SIGINT
    if (sigaction(SIGINT, NULL, &current_sa) == -1) {
        exit(EXIT_FAILURE); // Exit with a generic failure code if sigaction fails to retrieve the handler
    }
    if (current_sa.sa_handler != signal_handler) {
        exit(EXIT_FAILURE); // Exit with a generic failure code if the handler doesn't match
    }
    if ((current_sa.sa_flags & SA_RESETHAND) != SA_RESETHAND) {
        exit(EXIT_FAILURE); // Exit with a generic failure code if the SA_RESETHAND flag is not set
    }

    pid_t pid = fork();
    if (pid == -1) {
        // Fork failed
        exit(EXIT_FAILURE); // Exit with a generic failure code if fork fails
    } else if (pid == 0) {
        // Child process
        close(pipefd[0]); // Close unused read end

        // Wait for parent to be ready
        read(pipefd[0], &buf, 1);

        // Send SIGINT to parent process
        kill(getppid(), SIGINT);
        exit(EXIT_SUCCESS);
    } else {
        // Parent process
        close(pipefd[1]); // Close unused write end

        // Signal child that parent is ready
        write(pipefd[1], "r", 1);

        pause(); // Wait for the signal

        // Check if the signal handler was invoked
        if (!handler_invoked) {
            exit(EXIT_FAILURE); // Exit with a generic failure code if handler was not invoked
        }

        // Query the current signal handler for SIGINT
        if (sigaction(SIGINT, NULL, &current_sa) == -1) {
            exit(EXIT_FAILURE); // Exit with a generic failure code if sigaction fails to retrieve the handler
        }
        if (current_sa.sa_handler != SIG_DFL) {
            exit(EXIT_FAILURE); // Exit with a generic failure code if the handler is not reset to default
        }

        // Additional checks can be added here if necessary

        exit(EXIT_SUCCESS);
    }
}
